import{c as t,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"GetSpecialMDLConfig","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetSpecialMDLConfig","slug":"getspecialmdlconfig"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetSpecialMDLConfig.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetSpecialMDLConfig.md"}'),l={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetSpecialMDLConfig.md"};function i(p,a,d,r,o,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="getspecialmdlconfig" tabindex="-1">GetSpecialMDLConfig <a class="header-anchor" href="#getspecialmdlconfig" aria-label="Permalink to &quot;GetSpecialMDLConfig&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于配置SpecialMDL模板的参数，获取自定义SpecialMDL模板。SpecialMDL模板的介绍请参考<a href="./MatmulConfig.html#table6981133810309">表 模板特性</a>。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ constexpr MatmulConfig GetSpecialMDLConfig(const bool intrinsicsLimit = false, const bool batchLoop = false, const uint32_t doMTE2Preload = 0, const bool isVecND2NZ = false, bool isPerTensor = false, bool hasAntiQuantOffset = false)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p>本接口的所有参数用于设置<a href="./MatmulConfig.html#table1761013213153">MatmulConfig结构体</a>中的参数，其中互相对应的参数的功能作用相同。</p><p><strong>表 1</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>intrinsicsLimit</td><td>输入</td><td>用于设置参数intrinsicsCheck。 当左矩阵或右矩阵在单核上内轴（即尾轴）大于等于65535（元素个数）时，是否使能循环执行数据从Global Memory到L1 Buffer的搬入。例如，左矩阵A[M, K]，单核上的内轴数据singleCoreK大于65535，配置该参数为true后，API内部通过循环执行数据的搬入。参数取值如下： false：当左矩阵或右矩阵在单核上内轴大于等于65535时，不使能循环执行数据的搬入（默认值）。true：当左矩阵或右矩阵在单核上内轴大于等于65535时，使能循环执行数据的搬入。 对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</td></tr><tr><td>batchLoop</td><td>输入</td><td>用于设置参数isNBatch。 是否多Batch输入多Batch输出。仅对BatchMatmul有效，使能该参数后，仅支持Norm模板，且需调用IterateNBatch实现多Batch输入多Batch输出。参数取值如下： false：不使能多Batch（默认值）。true：使能多Batch。</td></tr><tr><td>doMTE2Preload</td><td>输入</td><td>用于设置参数doMTE2Preload。 在MTE2流水间隙较大，且M/N数值较大时可通过该参数开启对应M/N方向的预加载功能，开启后能减小MTE2间隙，提升性能。预加载功能仅在MDL模板有效（不支持SpecialMDL模板）。参数取值如下： 0：不开启（默认值）。1：开启M方向preload。2：开启N方向preload。 注意：开启M/N方向的预加载功能时需保证K全载且M/N方向开启DoubleBuffer；其中，M方向的K全载条件为：singleCoreK/baseK &lt;= stepKa；N方向的K全载条件为：singleCoreK/baseK &lt;= stepKb。</td></tr><tr><td>isVecND2NZ</td><td>输入</td><td>预留参数，保持默认值false即可。</td></tr><tr><td>isPerTensor</td><td>输入</td><td>用于设置参数isPerTensor。 A矩阵half类型输入且B矩阵int8_t类型输入场景，使能B矩阵量化时是否为per tensor。 true：per tensor量化。false：per channel量化。 对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</td></tr><tr><td>hasAntiQuantOffset</td><td>输入</td><td>用于设置参数hasAntiQuantOffset。 A矩阵half类型输入且B矩阵int8_t类型输入场景，使能B矩阵量化时是否使用offset系数。 对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p><a href="./MatmulConfig.html#table1761013213153">MatmulConfig结构体</a>。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 配置SpecialMDL模板的参数，获取自定义SpecialMDL模板</span></span>
<span class="line"><span>constexpr MatmulConfig MM_CFG = GetSpecialMDLConfig(</span></span>
<span class="line"><span>    /* intrinsicsLimit      */ false,</span></span>
<span class="line"><span>    /* batchLoop            */ false,</span></span>
<span class="line"><span>    /* doMTE2Preload        */ 0,</span></span>
<span class="line"><span>    /* isVecND2NZ           */ false,</span></span>
<span class="line"><span>    /* isPerTensor          */ false,</span></span>
<span class="line"><span>    /* hasAntiQuantOffset   */ false</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>// 常规Matmul计算，最后输出使用自定义SpecialMDL模板的计算结果</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, MM_CFG&gt; mm;</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>if (tiling.isBias) {</span></span>
<span class="line"><span>    mm.SetBias(gmBias);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>mm.IterateAll(gm_c);</span></span>
<span class="line"><span>mm.End();</span></span></code></pre></div>`,17)])])}const m=t(l,[["render",i]]);export{f as __pageData,m as default};
